#!/usr/bin/env node
/*
 * Discord Game Simulator
 * ------------------------------------------------------------------
 * Spawns a tiny fake Windows process named after a real "detectable"
 * game so Discord's game detection fires, letting PLAY_ON_DESKTOP
 * playtime accrue without you owning the game.
 *
 * Single file, no dependencies. Run:  node discord-game-simulator.js
 * UI:      http://127.0.0.1:8787
 *
 * How it works
 *   1. GET https://discord.com/api/applications/detectable  (public)
 *      -> every game Discord can auto-detect, with its real exe name.
 *   2. We write an embedded ~15KB GUI .exe (hidden window + idle loop)
 *      to  ~/.discord-game-sim/games/<id>/<folder>/<exe>  and spawn it.
 *   3. Discord sees a matching process -> "Playing <Game>" + playtime accrual.
 *
 * The HTML UI and the dummy exe are inlined below as string constants.
 */
'use strict';

const http    = require('http');
const https   = require('https');
const fs      = require('fs');
const path    = require('path');
const os      = require('os');
const crypto  = require('crypto');
const { spawn } = require('child_process');

// Inlined assets (filled by the build step).
const UI_HTML      = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Discord Game Simulator</title>\n<style>\n  :root{\n    --bg:#1e1f22; --panel:#2b2d31; --panel2:#232428; --blurple:#5865f2;\n    --blurple-h:#4752c4; --text:#dbdee1; --muted:#949ba4; --green:#23a55a;\n    --red:#f23f43; --line:#1a1b1e; --amber:#f0b232;\n  }\n  *{box-sizing:border-box}\n  html,body{margin:0;padding:0}\n  body{\n    background:radial-gradient(1200px 600px at 50% -10%, #26272b 0%, var(--bg) 60%);\n    color:var(--text); font:15px/1.5 -apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    min-height:100vh;\n  }\n  .wrap{max-width:920px; margin:0 auto; padding:28px 18px 60px}\n  header{display:flex; align-items:center; gap:14px; margin-bottom:6px}\n  .logo{\n    width:46px;height:46px;border-radius:14px;flex:0 0 auto;\n    background:linear-gradient(135deg,#5865f2,#7b6cff);\n    display:grid;place-items:center;font-size:24px;box-shadow:0 6px 18px rgba(88,101,242,.35);\n  }\n  h1{font-size:22px;margin:0}\n  .sub{color:var(--muted);font-size:13px;margin:0}\n  .banner{\n    display:none;align-items:center;gap:10px;margin:18px 0 0;padding:11px 14px;border-radius:12px;\n    background:rgba(35,165,90,.12);border:1px solid rgba(35,165,90,.4);color:#7ee2a8;font-size:14px;\n  }\n  .banner.on{display:flex}\n  .dot{width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 0 0 rgba(35,165,90,.6);animation:pulse 1.6s infinite}\n  @keyframes pulse{0%{box-shadow:0 0 0 0 rgba(35,165,90,.5)}70%{box-shadow:0 0 0 7px rgba(35,165,90,0)}100%{box-shadow:0 0 0 0 rgba(35,165,90,0)}}\n\n  /* Active sims */\n  .section{margin-top:22px}\n  .section h2{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:0 0 10px}\n  .card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px}\n  .empty{color:var(--muted);font-size:14px;padding:6px 2px}\n  .sim{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--line)}\n  .sim:first-child{border-top:0;padding-top:2px}\n  .sim .ic{width:40px;height:40px;border-radius:10px;background:var(--panel2);object-fit:cover;flex:0 0 auto}\n  .sim .meta{flex:1;min-width:0}\n  .sim .nm{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .sim .ex{color:var(--muted);font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .bar{height:6px;border-radius:6px;background:var(--panel2);overflow:hidden;margin-top:7px}\n  .bar i{display:block;height:100%;background:linear-gradient(90deg,var(--blurple),#7b6cff);width:0%}\n  .timer{font-variant-numeric:tabular-nums;color:var(--text);font-size:14px;min-width:96px;text-align:right}\n  .timer small{color:var(--muted)}\n\n  /* Controls */\n  .controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:18px}\n  input[type=search],select{\n    background:var(--panel2);border:1px solid var(--line);color:var(--text);\n    border-radius:10px;padding:10px 12px;font-size:14px;outline:none;\n  }\n  input[type=search]{flex:1;min-width:220px}\n  input[type=search]:focus,select:focus,input[type=text]:focus{border-color:var(--blurple)}\n  select{cursor:pointer}\n  .count{color:var(--muted);font-size:13px;white-space:nowrap}\n\n  /* Custom */\n  .custom{margin-top:12px;display:none}\n  .custom.on{display:block}\n  .custom .row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n  .custom input[type=text]{flex:1;min-width:160px;background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:10px;padding:10px 12px;font-size:14px;outline:none}\n  .chk{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:13px;cursor:pointer;user-select:none}\n  .chk input{width:16px;height:16px;accent-color:var(--blurple)}\n\n  /* Game list */\n  .list{margin-top:14px;display:flex;flex-direction:column;gap:8px}\n  .game{\n    display:flex;align-items:center;gap:12px;background:var(--panel);border:1px solid var(--line);\n    border-radius:12px;padding:10px 12px;transition:border-color .15s,background .15s;\n  }\n  .game:hover{border-color:#3a3c41;background:#2f3136}\n  .game .ic{width:42px;height:42px;border-radius:10px;background:var(--panel2);object-fit:cover;flex:0 0 auto}\n  .game .meta{flex:1;min-width:0}\n  .game .nm{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .game .ex{color:var(--muted);font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .game.live{border-color:rgba(88,101,242,.6);background:rgba(88,101,242,.08)}\n\n  .btn{\n    border:0;border-radius:10px;padding:9px 16px;font-size:14px;font-weight:600;cursor:pointer;\n    background:var(--blurple);color:#fff;white-space:nowrap;transition:background .15s,transform .05s;\n  }\n  .btn:hover{background:var(--blurple-h)}\n  .btn:active{transform:translateY(1px)}\n  .btn.stop{background:var(--red)}\n  .btn.stop:hover{background:#d63438}\n  .btn.ghost{background:var(--panel2);color:var(--text);border:1px solid var(--line)}\n  .btn.ghost:hover{background:#33353a}\n  .btn:disabled{opacity:.5;cursor:not-allowed}\n\n  .foot{margin-top:34px;color:var(--muted);font-size:12.5px;line-height:1.7;border-top:1px solid var(--line);padding-top:16px}\n  .foot b{color:var(--text)}\n  .err{background:rgba(242,63,67,.12);border:1px solid rgba(242,63,67,.4);color:#ff9a9c;padding:10px 12px;border-radius:10px;margin-top:12px;font-size:13px;display:none}\n  .err.on{display:block}\n  .stale{display:none;align-items:flex-start;gap:10px;margin-top:16px;padding:12px 14px;border-radius:12px;background:rgba(242,63,67,.15);border:1px solid rgba(242,63,67,.55);color:#ffb3b6;font-size:13.5px;line-height:1.5}\n  .stale.on{display:flex}\n  .stale b{color:#ff6b74}\n  .stale .sicon{font-size:18px;line-height:1.2}\n  .rng{display:none;gap:8px;align-items:center}\n  .rng.on{display:inline-flex}\n  .rng input[type=number]{width:76px;background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:10px;padding:9px 10px;font-size:14px;outline:none}\n  .rng input[type=number]:focus{border-color:var(--blurple)}\n  .rng .lbl{color:var(--muted);font-size:13px}\n  .queue{margin-top:22px}\n  .queue .qhead{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n  .queue .qhead h2{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin:0 10px 0 0;flex:1}\n  .qitem{display:flex;align-items:center;gap:10px;padding:8px 0;border-top:1px solid var(--line)}\n  .qitem:first-of-type{border-top:0}\n  .qitem .meta{flex:1;min-width:0}\n  .qitem .nm{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .qitem .ex{color:var(--muted);font-size:12px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .qitem .ord{width:22px;height:22px;border-radius:7px;background:var(--panel2);color:var(--muted);display:grid;place-items:center;font-size:12px;flex:0 0 auto}\n  .qbtn{border:0;border-radius:8px;background:var(--panel2);color:var(--text);padding:6px 9px;font-size:13px;cursor:pointer}\n  .qbtn:hover{background:#33353a}\n  .btns{display:flex;gap:8px;align-items:center;flex:0 0 auto}\n  .gapbar{display:flex;align-items:center;gap:10px;margin-top:10px;padding:10px 12px;border-radius:10px;background:rgba(240,178,50,.1);border:1px solid rgba(240,178,50,.35);color:#f3cf8a;font-size:13px}\n  .gapbar .gdot{width:9px;height:9px;border-radius:50%;background:var(--amber);animation:pulse 1.4s infinite}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <div class=\"logo\">🎮</div>\n    <div>\n      <h1>Discord Game Simulator</h1>\n      <p class=\"sub\">Fake a game process so Discord shows you're playing — no install needed.</p>\n    </div>\n  </header>\n\n  <div class=\"banner\" id=\"banner\"><span class=\"dot\"></span><span id=\"banner-text\">Simulating…</span></div>\n  <div class=\"err\" id=\"err\"></div>\n  <div class=\"stale\" id=\"stale\"><span class=\"sicon\">⚠️</span><span><b>Stale server detected.</b> This page is newer than the server running it, so some actions (like the queue Stop) will fail with “not found”. Stop the running instance (Ctrl+C in its console window, or end it in Task Manager) and start it again, then refresh this page.</span></div>\n\n  <div class=\"section\">\n    <h2>Now faking</h2>\n    <div class=\"card\" id=\"active-card\">\n      <div class=\"empty\" id=\"active-empty\">Nothing running. Pick a game below and hit Simulate.</div>\n      <div id=\"active-list\"></div>\n    </div>\n  </div>\n\n  <div class=\"controls\">\n    <input type=\"search\" id=\"search\" placeholder=\"Search games…\">\n    <select id=\"duration\" title=\"How long to keep the fake process alive\">\n        <option value=\"300\">5 min</option>\n        <option value=\"900\" selected>15 min</option>\n        <option value=\"1800\">30 min</option>\n        <option value=\"3600\">1 hour</option>\n        <option value=\"7200\">2 hours</option>\n        <option value=\"0\">Indefinite (until stopped)</option>\n      </select>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"rand-toggle\"> Random</label>\n      <span class=\"rng\" id=\"rng\">\n        <span class=\"lbl\">from</span><input type=\"number\" id=\"dur-min\" min=\"0\" max=\"1440\" step=\"1\" value=\"15\">\n        <span class=\"lbl\">to</span><input type=\"number\" id=\"dur-max\" min=\"0\" max=\"1440\" step=\"1\" value=\"30\">\n        <span class=\"lbl\">min</span>\n      </span>\n    <button class=\"btn ghost\" id=\"refresh\">↻ Refresh list</button>\n    <label class=\"chk\"><input type=\"checkbox\" id=\"custom-toggle\"> Custom process</label>\n    <label class=\"chk\"><input type=\"checkbox\" id=\"show-toggle\"> Hide window</label>\n  </div>\n\n  <div class=\"custom\" id=\"custom-wrap\">\n    <div class=\"row\">\n      <input type=\"text\" id=\"custom-name\" placeholder=\"Game name (shown in status)\">\n      <input type=\"text\" id=\"custom-exe\" placeholder=\"exe name e.g. mygame.exe (folder/name ok)\">\n      <button class=\"btn\" id=\"custom-start\">Simulate custom</button>\n    </div>\n    <div class=\"sub\" style=\"margin-top:6px\">Use this for a game not in the detectable list. The exe name must match what Discord looks for.</div>\n  </div>\n\n  <div class=\"queue\">\n    <div class=\"card\">\n      <div class=\"qhead\">\n        <h2>Queue <span class=\"count\" id=\"qcount\"></span></h2>\n        <button class=\"btn\" id=\"q-start\">▶ Start queue</button>\n        <button class=\"btn ghost\" id=\"q-clear\">Clear</button>\n        <button class=\"btn stop\" id=\"q-stop\" style=\"display:none\">■ Stop</button>\n      </div>\n      <div id=\"q-list\"><div class=\"empty\" id=\"q-empty\">Add games to run one after another — a random 1–3 min gap is added between each so it doesn't look scripted.</div></div>\n      <div class=\"gapbar\" id=\"gapbar\" style=\"display:none\"><span class=\"gdot\"></span><span id=\"gaptext\">Waiting…</span></div>\n    </div>\n  </div>\n\n  <div class=\"section\">\n    <h2>Games <span class=\"count\" id=\"count\"></span></h2>\n    <div class=\"list\" id=\"game-list\"><div class=\"empty\">Loading detectable games…</div></div>\n  </div>\n\n  <div class=\"foot\">\n    <b>How it works:</b> Discord reads your Windows process list and matches it against its public\n    <code>/applications/detectable</code> database — it matches the running process <b>and</b> a visible window. This tool\n    writes a ~15&nbsp;KB dummy executable with that exact name (mirroring the game's folder layout) into\n    <code>~/.discord-game-sim/games/&lt;id&gt;/…</code> and keeps it alive. Discord then shows\n    \"Playing &lt;Game&gt;\" and accrues PLAY_ON_DESKTOP playtime — accept the quest in Discord first.<br>\n    <b>Verification:</b> each sim shows <b>✓ running</b> when it's confirmed in your process list, or\n    <b>⚠ exited early</b> if it died — the usual cause is Windows Defender / antivirus quarantining the\n    unsigned exe. If that happens, add the <code>.discord-game-sim</code> folder to your antivirus exclusions.\n    <b>Tip:</b> a 15-min play session needs the process alive ~15&nbsp;min. Discord registers the game from a\n    <b>visible</b> window, so the fake game window stays on your desktop — you can minimize it. Tick\n    <b>Hide window</b> only if you don't care about detection. Stop it (or let the timer end) when done.\n  </div>\n</div>\n\n<script>\n(function () {\n  const $ = (s) => document.querySelector(s);\n  const state = { games: [], filtered: [], byId: {} };\n  const activeIds = new Set();\n  const queueItems = [];\n  const UI_VERSION = '2026-09-06-4';\n  let staleChecked = false;\n\n  function checkStale() {\n    if (staleChecked) return;\n    fetch('/api/health').then(r => r.json()).then(j => {\n      if (j.version && j.version !== UI_VERSION) { const el = $('#stale'); if (el) el.classList.add('on'); }\n      staleChecked = true;\n    }).catch(() => { staleChecked = true; });\n  }\n\n  const fmt = (s) => {\n    s = Math.max(0, s | 0);\n    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), ss = s % 60;\n    return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(ss).padStart(2, '0');\n  };\n\n  function iconUrl(g) {\n    return g.icon || 'https://cdn.discordapp.com/app-icons/' + g.id + '/placeholder.png';\n  }\n  function img(g) {\n    const el = document.createElement('img');\n    el.className = 'ic'; el.alt = ''; el.loading = 'lazy';\n    el.src = iconUrl(g);\n    el.onerror = () => { el.style.visibility = 'hidden'; };\n    return el;\n  }\n\n  function renderGames() {\n    const list = $('#game-list');\n    list.innerHTML = '';\n    if (!state.filtered.length) { list.innerHTML = '<div class=\"empty\">No games match.</div>'; return; }\n    const frag = document.createDocumentFragment();\n    state.filtered.forEach((g) => {\n      const row = document.createElement('div');\n      row.className = 'game' + (activeIds.has(g.id) ? ' live' : '');\n      row.dataset.id = g.id;\n      row.appendChild(img(g));\n      const meta = document.createElement('div'); meta.className = 'meta';\n      const nm = document.createElement('div'); nm.className = 'nm'; nm.textContent = g.name;\n      const ex = document.createElement('div'); ex.className = 'ex'; ex.textContent = g.exe;\n      meta.appendChild(nm); meta.appendChild(ex);\n      row.appendChild(meta);\n      const qbtn = document.createElement('button');\n      qbtn.className = 'qbtn';\n      qbtn.textContent = '+ Queue';\n      qbtn.title = 'Add to queue';\n      qbtn.onclick = () => addToQueue(g);\n      row.appendChild(qbtn);\n      const btn = document.createElement('button');\n      btn.className = 'btn' + (activeIds.has(g.id) ? ' stop' : '');\n      btn.textContent = activeIds.has(g.id) ? 'Stop' : 'Simulate';\n      btn.onclick = () => toggle(g.id);\n      row.appendChild(btn);\n      frag.appendChild(row);\n    });\n    list.appendChild(frag);\n  }\n\n  function renderActive(list) {\n    const wrap = $('#active-list');\n    const empty = $('#active-empty');\n    wrap.innerHTML = '';\n    empty.style.display = list.length ? 'none' : 'block';\n    const banner = $('#banner');\n    if (list.length) {\n      banner.classList.add('on');\n      $('#banner-text').textContent = 'Simulating ' + list.map(s => s.name).join(', ') + ' — ' + fmt(list[0].elapsedSec) + ' elapsed';\n    } else banner.classList.remove('on');\n\n    list.forEach((s) => {\n      const row = document.createElement('div'); row.className = 'sim';\n      const ic = document.createElement('div'); ic.className = 'ic'; ic.textContent = '🎮';\n      const meta = document.createElement('div'); meta.className = 'meta';\n      const nm = document.createElement('div'); nm.className = 'nm'; nm.textContent = s.name;\n      const ex = document.createElement('div'); ex.className = 'ex';\n      const st = s.running ? (s.confirmed === false ? '  ·  ✗ not in process list' : '  ·  ✓ running') : (s.exitedEarly ? '  ·  ⚠ exited early (code ' + s.exitCode + ')' : '  ·  stopped');\n      ex.textContent = s.exe + '  ·  pid ' + s.pid + st;\n      const pf = document.createElement('div'); pf.className = 'ex'; pf.textContent = s.file; pf.title = 'Executable path (add to antivirus exclusion if it dies)';\n      meta.appendChild(nm); meta.appendChild(ex); meta.appendChild(pf);\n      const dur = s.durationSec || 0;\n      const pct = dur ? Math.min(100, (s.elapsedSec / dur) * 100) : 100;\n      const bar = document.createElement('div'); bar.className = 'bar';\n      const fill = document.createElement('i'); fill.style.width = (dur ? pct : 100) + '%';\n      bar.appendChild(fill); meta.appendChild(bar);\n      const timer = document.createElement('div'); timer.className = 'timer';\n      timer.innerHTML = fmt(s.elapsedSec) + (dur ? ' <small>/ ' + fmt(dur) + '</small>' : ' <small>∞</small>');\n      row.appendChild(ic); row.appendChild(meta); row.appendChild(timer);\n      const btn = document.createElement('button'); btn.className = 'btn stop'; btn.textContent = 'Stop';\n      btn.onclick = () => stop(s.id);\n      row.appendChild(btn);\n      wrap.appendChild(row);\n    });\n  }\n\n  async function api(path, body) {\n    const opt = (body !== undefined) ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : {};\n    const r = await fetch('/api/' + path, opt);\n    const j = await r.json().catch(() => ({}));\n    if (!r.ok) throw new Error(j.error || ('HTTP ' + r.status));\n    return j;\n  }\n\n  function showErr(msg) { const e = $('#err'); e.textContent = msg; e.classList.add('on'); setTimeout(() => e.classList.remove('on'), 6000); }\n\n  async function loadGames(refresh) {\n    try {\n      const j = await api('games' + (refresh ? '?refresh=1' : ''));\n      state.games = j.games;\n      state.byId = {}; state.games.forEach(g => state.byId[g.id] = g);\n      applyFilter();\n      $('#count').textContent = '· ' + j.count + ' detectable';\n    } catch (e) { showErr('Could not load games: ' + e.message); }\n  }\n\n  function applyFilter() {\n    const q = $('#search').value.trim().toLowerCase();\n    state.filtered = q\n      ? state.games.filter(g => (g.name + ' ' + (g.aliases || []).join(' ')).toLowerCase().includes(q))\n      : state.games;\n    renderGames();\n  }\n\n  function durationPayload() {\n    if ($('#rand-toggle').checked) {\n      const minM = Math.max(0, parseInt($('#dur-min').value, 10) || 0);\n      const maxM = Math.max(minM, parseInt($('#dur-max').value, 10) || minM);\n      return { durationMinSec: minM * 60, durationMaxSec: maxM * 60 };\n    }\n    const s = parseInt($('#duration').value, 10) || 0;\n    return { durationSec: s, durationMinSec: s, durationMaxSec: s };\n  }\n\n  async function toggle(id) {\n    if (activeIds.has(id)) { stop(id); return; }\n    try {\n      const j = await api('start', { appid: id, hide: $('#show-toggle').checked, ...durationPayload() });\n      activeIds.add(id);\n      renderGames();\n      poll();\n    } catch (e) { showErr('Start failed: ' + e.message); }\n  }\n\n  async function stop(id) {\n    try {\n      const j = await api('stop', { id });\n      renderActive(j.active);\n      syncButtons();\n      if (id !== 'all') activeIds.delete(id);\n      renderGames();\n    } catch (e) { showErr('Stop failed: ' + e.message); }\n  }\n\n  function syncButtons() {\n    // reflect server truth onto the game rows\n    document.querySelectorAll('.game').forEach(row => {\n      const on = activeIds.has(row.dataset.id);\n      row.classList.toggle('live', on);\n      const b = row.querySelector('.btn');\n      b.className = 'btn' + (on ? ' stop' : '');\n      b.textContent = on ? 'Stop' : 'Simulate';\n    });\n  }\n\n  async function poll() {\n    try {\n      const j = await api('status');\n      activeIds.clear();\n      (j.active || []).forEach(s => activeIds.add(s.id));\n      renderActive(j.active);\n      syncButtons();\n      renderQueue(j.queue || { running: false, queue: [], gap: null });\n    } catch (_) {}\n  }\n\n  function addToQueue(g) {\n    const dur = durationPayload();\n    const item = { id: g.id, name: g.name, exe: g.exe, hide: $('#show-toggle').checked, durationMinSec: dur.durationMinSec || 0, durationMaxSec: dur.durationMaxSec || dur.durationMinSec || 0 };\n    if (!queueItems.some(q => q.id === item.id)) queueItems.push(item);\n    renderQueue({ running: false, queue: [], gap: null });\n  }\n\n  function renderQueue(sq) {\n    const running = !!(sq && sq.running);\n    const items = running ? (sq.queue || []) : queueItems;\n    const list = $('#q-list');\n    list.innerHTML = '';\n    $('#qcount').textContent = items.length ? '· ' + items.length : '';\n    $('#q-start').style.display = running ? 'none' : '';\n    $('#q-clear').style.display = running ? 'none' : '';\n    $('#q-stop').style.display = running ? '' : 'none';\n    $('#q-start').disabled = !queueItems.length;\n    const gapbar = $('#gapbar');\n    if (running && sq.gap) { gapbar.style.display = 'flex'; $('#gaptext').textContent = 'Waiting ' + sq.gap.secLeft + 's before ' + sq.gap.name + '…'; }\n    else if (running) { gapbar.style.display = 'flex'; $('#gaptext').textContent = 'Running…'; }\n    else gapbar.style.display = 'none';\n    if (!items.length) { const e = document.createElement('div'); e.className = 'empty'; e.textContent = running ? 'Queue running…' : 'Add games to run one after another — a random 1–3 min gap is added between each so it does not look scripted.'; list.appendChild(e); return; }\n    items.forEach((q, i) => {\n      const row = document.createElement('div'); row.className = 'qitem';\n      const ord = document.createElement('div'); ord.className = 'ord';\n      ord.textContent = running ? (activeIds.has(q.id) ? '▶' : (sq.gap && sq.gap.id === q.id ? '⏳' : (i + 1))) : (i + 1);\n      const meta = document.createElement('div'); meta.className = 'meta';\n      const nm = document.createElement('div'); nm.className = 'nm'; nm.textContent = q.name;\n      const ex = document.createElement('div'); ex.className = 'ex';\n      const durTxt = q.durationMinSec === q.durationMaxSec ? fmt(q.durationMinSec) + 's' : fmt(q.durationMinSec) + '–' + fmt(q.durationMaxSec) + 's';\n      ex.textContent = q.exe + '  ·  ' + durTxt;\n      meta.appendChild(nm); meta.appendChild(ex);\n      const btns = document.createElement('div'); btns.className = 'btns';\n      if (!running) { const rm = document.createElement('button'); rm.className = 'qbtn'; rm.textContent = '✕'; rm.title = 'Remove'; rm.onclick = () => { const n = queueItems.indexOf(q); if (n >= 0) queueItems.splice(n, 1); renderQueue({ running: false, queue: [], gap: null }); }; btns.appendChild(rm); }\n      row.appendChild(ord); row.appendChild(meta); row.appendChild(btns);\n      list.appendChild(row);\n    });\n  }\n\n  // wire up\n  $('#search').addEventListener('input', applyFilter);\n  $('#refresh').addEventListener('click', () => loadGames(true));\n  $('#rand-toggle').addEventListener('change', (e) => $('#rng').classList.toggle('on', e.target.checked));\n  $('#q-start').addEventListener('click', async () => {\n    if (!queueItems.length) return;\n    try { await api('queue/run', { items: queueItems.map(j => ({ id: j.id, name: j.name, exe: j.exe, durationMinSec: j.durationMinSec, durationMaxSec: j.durationMaxSec, hide: j.hide })) }); queueItems.length = 0; poll(); } catch (e) { showErr(e.message); }\n  });\n  $('#q-clear').addEventListener('click', () => { queueItems.length = 0; renderQueue({ running: false, queue: [], gap: null }); });\n  $('#q-stop').addEventListener('click', async () => { try { await api('queue/stop', {}); poll(); } catch (e) { showErr(e.message); } });\n  $('#custom-toggle').addEventListener('change', (e) => $('#custom-wrap').classList.toggle('on', e.target.checked));\n  $('#custom-start').addEventListener('click', async () => {\n    const name = $('#custom-name').value.trim() || 'Custom Game';\n    const exe = $('#custom-exe').value.trim();\n    if (!exe) { showErr('Enter an exe name.'); return; }\n    const dur = parseInt($('#duration').value, 10) || 0;\n    try { await api('start', { custom: true, name, exe, durationSec: dur, hide: $('#show-toggle').checked }); poll(); }\n    catch (e) { showErr('Start failed: ' + e.message); }\n  });\n\n  checkStale();\n  loadGames(false);\n  poll();\n  setInterval(poll, 1000);\n})();\n</script>\n</body>\n</html>\n";
const DUMMY_EXE_B64 = "";

const PORT = parseInt(process.env.PORT || '8787', 10);
const HOST = process.env.HOST || '127.0.0.1';

// Bump on every change so the UI can detect when it's talking to a STALE server
// (one started before this code was written). A running Node server only loads
// its routes at startup, so an old instance serves old routes while the browser
// shows the new UI — the version mismatch is how the UI knows to say "restart".
const VERSION = '2026-09-06-4';

// Always-writable location for the fake games.
const BASE_DIR = path.join(os.homedir(), '.discord-game-sim', 'games');

// Small offline fallback so the UI still works without a network.
const FALLBACK_GAMES = [
  { id: '356875221078245376', name: 'Overwatch',            exe: 'overwatch.exe',        icon: 'https://cdn.discordapp.com/app-icons/356875221078245376/a60bb76ba4d4acafbd4cb9aad6e61739.png' },
  { id: '356875762940379136', name: 'World of Warcraft',    exe: '_retail_/wow-64.exe',  icon: 'https://cdn.discordapp.com/app-icons/356875762940379136/fc92f820c44e72085dc6205e5e746850.png' },
  { id: '356877880938070016', name: 'Rocket League',        exe: 'rocketleague.exe',     icon: 'https://cdn.discordapp.com/app-icons/356877880938070016/a74899a5190c48a3e6ce9f8d2eaff348.png' },
  { id: '356875988589740042', name: 'Dota 2',               exe: 'dota2.exe',            icon: 'https://cdn.discordapp.com/app-icons/356875988589740042/6b4b3fa4c83555d3008de69d33a60588.png' },
  { id: '357607133254254632', name: 'Dead by Daylight',     exe: 'deadbydaylight.exe',   icon: 'https://cdn.discordapp.com/app-icons/357607133254254632/64e7623c9af49f2e7dc7048df16b1013.png' },
  { id: '357607478105604096', name: 'War Thunder',          exe: 'aces.exe',             icon: 'https://cdn.discordapp.com/app-icons/357607478105604096/b23dfa191e3f3aa8142572110a99723f.png' },
  { id: '356889262362329098', name: 'FINAL FANTASY XIV ONLINE', exe: 'ffxiv.exe',        icon: 'https://cdn.discordapp.com/app-icons/356889262362329098/8fbbc6725f295195c8dd4f390ccd8611.png' },
  { id: '356887282982191114', name: 'ARK: Survival Evolved', exe: 'shootergame.exe',     icon: 'https://cdn.discordapp.com/app-icons/356887282982191114/99016e1224cc0bb19604048f07bc937a.png' },
];

// Runtime state: id -> { name, exe, file, pid, startedAt, durationSec, child, timer }
const active = new Map();
const pendingSpawns = new Map(); // id -> child, for spawns not yet confirmed (pid not set)
let gamesCache = null;
let dummyBuf  = null;

// Queue: the client builds a batch of jobs and sends it; the server runs them
// one after another, inserting a random 1–3 min gap between each launch.
let queueRun = null; // { idx, items, gap: {name, until} | null, timer: number|null }

function log(...a) { console.log(new Date().toISOString().slice(11, 19), ...a); }
function dummyBuffer() { if (!dummyBuf) dummyBuf = Buffer.from(DUMMY_EXE_B64, 'base64'); return dummyBuf; }

/* ----------------------------- HTTP helpers ----------------------------- */

function httpsGetJson(url, timeoutMs = 20000) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0 (DiscordGameSim/1.0)' } }, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error('bad json: ' + data.slice(0, 120))); }
      });
    });
    req.on('error', reject);
    req.setTimeout(timeoutMs, () => req.destroy(new Error('timeout')));
  });
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (c) => { data += c; if (data.length > 1e6) req.destroy(); });
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch { resolve({}); }
    });
    req.on('error', reject);
  });
}

function sendJson(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(body);
}

/* --------------------------- Detectable games --------------------------- */

function pickWinExe(win) {
  // Choose the most "game-like" executable among the win32 candidates:
  // prefer a real .exe that is not a launcher and not a beta/ptr/dev branch.
  const score = (e) => {
    let s = 0;
    const full = (e.name || '');
    const base = full.split(/[\\/]/).pop();
    if (e.is_launcher) s -= 100;
    if (!/\.exe$/i.test(base)) s -= 50;
    if (/\/_beta_\/|\/_ptr_\/|\/_dev_\//i.test(full)) s -= 20;
    if (full.includes('/') || full.includes('\\')) s -= 5;
    return s;
  };
  return win.slice().sort((a, b) => score(b) - score(a))[0];
}

function normalizeGame(g) {
  const win = (g.executables || []).filter((e) => e.os === 'win32');
  const best = pickWinExe(win) || (g.executables || [])[0] || {};
  const exePath = best.name || '';
  const exe = exePath ? exePath.split(/[\\/]/).pop() : '';
  return {
    id: String(g.id),
    name: g.name,
    aliases: g.aliases || [],
    icon: g.icon_hash ? 'https://cdn.discordapp.com/app-icons/' + g.id + '/' + g.icon_hash + '.png' : '',
    exe,
    exePath,
  };
}

async function getGames(force) {
  if (gamesCache && !force) return gamesCache;
  let list;
  try {
    list = await httpsGetJson('https://discord.com/api/applications/detectable');
  } catch (e) {
    log('detectable fetch failed, using fallback:', e.message);
    list = FALLBACK_GAMES;
  }
  const games = (Array.isArray(list) ? list : [])
    .map(normalizeGame)
    .filter((g) => g.exe)
    .sort((a, b) => a.name.localeCompare(b.name));
  gamesCache = games;
  return games;
}

/* ------------------------------ Simulation ------------------------------ */

function buildGamePath(id, exeName) {
  const norm = exeName.replace(/\\/g, '/');
  const dir  = path.join(BASE_DIR, id, path.dirname(norm));
  const file = path.join(dir, path.basename(norm));
  return { dir, file };
}

function randInt(min, max) {
  min = Math.floor(min); max = Math.floor(max);
  if (max < min) max = min;
  return min + Math.floor(Math.random() * (max - min + 1));
}

// Pick a duration in seconds. Supports a fixed value (durationSec) or a random
// range (durationMinSec..durationMaxSec). Range wins when both bounds are given.
function pickDuration(req) {
  const min   = parseInt(req.durationMinSec, 10);
  const max   = parseInt(req.durationMaxSec, 10);
  const fixed = parseInt(req.durationSec, 10);
  const lo = Number.isFinite(min) ? min : (Number.isFinite(fixed) ? fixed : 0);
  const hi = (Number.isFinite(max) && max > lo) ? max : lo;
  return Math.max(0, Math.min(86400, randInt(lo, hi)));
}

async function resolveJob(req) {
  if (req.custom) {
    const name = String(req.name || 'Custom Game').slice(0, 80);
    let exe = String(req.exe || '').trim().replace(/\\/g, '/');
    if (!exe) throw new Error('exe name required');
    if (!/\.exe$/i.test(exe)) exe += '.exe';
    const id = 'custom_' + crypto.createHash('md5').update(name + '|' + exe).digest('hex').slice(0, 12);
    return { id, name, exe };
  }
  const games = await getGames();
  const g = games.find((x) => x.id === String(req.appid));
  if (!g) throw new Error('game not found');
  return { id: g.id, name: g.name, exe: g.exePath || g.exe };
}

function launchJob(job) {
  const { dir, file } = buildGamePath(job.id, job.exe);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(file, dummyBuffer());

  const args = [job.name];
  if (job.hide) args.push('--hide');
  // Spawn is async: on Windows child.pid is undefined until the 'spawn' event
  // fires, so resolve the job only once the child is actually up. Resolving
  // synchronously would leave statusFor() with a null pid (the "stop queue"
  // error) and kill() with no pid to target (the orphaned process).
  return new Promise((resolve, reject) => {
    // detached: the game window runs in its own process group so killChild can
    // take the whole tree down (see killChild below) instead of orphaning it.
    const child = spawn(file, args, { cwd: dir, windowsHide: false, stdio: 'ignore', detached: true });
    const entry = {
      id: job.id, name: job.name, exe: job.exe, file, pid: child.pid,
      startedAt: Date.now(), durationSec: job.durationSec, child,
      hide: !!job.hide, userStopped: false, exitCode: null, exitedEarly: false,
    };
    let settled = false;
    const finish = () => {
      if (entry.timer) { clearTimeout(entry.timer); entry.timer = null; }
      if (queueRun && queueRun.current === job.id) advanceQueue();
    };
    const settle = (fn, v) => { if (!settled) { settled = true; pendingSpawns.delete(String(job.id)); fn(v); } };
    const ok = (v) => settle(resolve, v);
    const fail = (e) => settle(reject, e);
    child.on('exit', (code) => {
      if (entry.exitCode === null) entry.exitCode = code;
      if (!entry.userStopped) { entry.exitedEarly = true; log('exited early', job.name, 'code=' + code, '(likely blocked by antivirus/Defender)'); }
      finish();
      ok(entry);
    });
    child.on('error', (e) => {
      log('spawn error', e.message);
      if (entry.exitCode === null) entry.exitCode = -1;
      entry.exitedEarly = true;
      finish();
      active.delete(String(job.id)); // don't leave a dead entry in the active list
      fail(new Error('spawn failed: ' + e.message));
    });
    child.on('spawn', () => {
      entry.pid = child.pid;
      ok(entry);
    });
    if (job.durationSec > 0) entry.timer = setTimeout(() => stopSim(job.id), (job.durationSec + 3) * 1000);

    // Track in-flight spawns so a stop/queue-stop issued before the 'spawn'
    // event fires can still reach the child (otherwise it's orphaned).
    pendingSpawns.set(String(job.id), child);
    active.set(job.id, entry);
    log('started', job.name, '->', file);
  });
}

// Force-kill a child process. child.kill() sends SIGTERM, which a Windows GUI
// .exe ignores — so the process was left orphaned and had to be killed by hand.
// Use taskkill /F /T on Windows (kills the whole process tree); SIGKILL to the
// process group elsewhere (the child is spawned detached, so its group is its pid).
function killChild(child) {
  try {
    if (!child) return;
    if (process.platform === 'win32' && child.pid) {
      const t = spawn('taskkill', ['/F', '/T', '/PID', String(child.pid)], { stdio: 'ignore' });
      t.on('error', () => {});
      return;
    }
    if (child.pid) {
      try { process.kill(-child.pid, 'SIGKILL'); } catch (_) {
        try { child.kill('SIGKILL'); } catch (_) {}
      }
    }
  } catch (_) {}
}

// Advance the queue: launch the first game straight away, then insert a random
// 1–3 min gap before each subsequent game so it doesn't look scripted.
function advanceQueue() {
  if (!queueRun) return;
  const next = queueRun.items[queueRun.idx];
  if (!next) { queueRun = null; log('queue finished'); return; }
  const launch = (j) => launchJob(j).catch((e) => { log('queue launch failed:', j.name, e.message); advanceQueue(); });
  if (queueRun.idx === 0) {
    // First game: launch straight away — no idle gap before it makes sense.
    queueRun.current = next.id;
    queueRun.idx += 1; // advance so this item's exit handler moves on to the next
    launch(next);
    return;
  }
  const gapSec = randInt(60, 180);
  queueRun.gap = { id: next.id, name: next.name, until: Date.now() + gapSec * 1000 };
  log('queue: gap ' + gapSec + 's before ' + next.name);
  queueRun.timer = setTimeout(() => {
    if (!queueRun) return;
    queueRun.gap = null;
    queueRun.current = next.id;
    queueRun.idx += 1; // advance so this item's exit handler moves on to the next
    launch(next);
  }, gapSec * 1000);
}

async function startQueue(items) {
  if (!Array.isArray(items) || !items.length) return false;
  if (active.size) [...active.keys()].forEach(stopSim); // stop in-flight sims first
  // Resolve each item's duration (fixed or random range) to a concrete second count
  // up front, so launchJob's auto-stop timer has a real value to work with. Also
  // resolve each item's exe to the FULL detectable path (e.g. bin/helldivers2.exe):
  // the client only sends the bare exe name, but Discord re-checks the FOLDER the
  // process runs from, so a nested-path game must land in the same folder as single
  // mode does — otherwise Discord detects it briefly, then drops it and won't re-detect.
  const games = await getGames();
  const byId = new Map(games.map((g) => [g.id, g]));
  const resolved = items.map((it) => {
    const g = byId.get(String(it.id));
    const exe = g ? (g.exePath || g.exe) : it.exe;
    return { ...it, exe, durationSec: pickDuration(it) };
  });
  queueRun = { idx: 0, items: resolved, gap: null, timer: null };
  advanceQueue();
  return true;
}

function stopQueue() {
  if (queueRun && queueRun.timer) { clearTimeout(queueRun.timer); queueRun.timer = null; }
  queueRun = null;
  if (active.size) [...active.keys()].forEach(stopSim);
  // Kill any in-flight spawn not yet in `active` (stopSim handles pendingSpawns
  // too, but be explicit so a mid-launch stop never orphans a process).
  for (const [id, child] of [...pendingSpawns]) {
    if (child && child.exitCode === null) killChild(child);
    pendingSpawns.delete(id);
  }
  log('queue stopped');
}

function queueState() {
  if (!queueRun) return { running: false, queue: [], gap: null };
  const gap = queueRun.gap ? { id: queueRun.gap.id, name: queueRun.gap.name, secLeft: Math.max(0, Math.ceil((queueRun.gap.until - Date.now()) / 1000)) } : null;
  return { running: true, queue: queueRun.items, gap };
}

async function startSim(req) {
  const job = await resolveJob(req);
  if (active.has(job.id)) throw new Error('already running');
  const durationSec = pickDuration(req);
  await launchJob({ ...job, durationSec, hide: !!req.hide });
  return statusFor(job.id);
}

function stopSim(id) {
  const e = active.get(String(id));
  if (e) {
    e.userStopped = true;
    if (e.timer) { clearTimeout(e.timer); e.timer = null; }
    if (e.child && e.child.exitCode === null) killChild(e.child);
    active.delete(String(id));
    log('stopped', e.name);
  }
  // Also kill a spawn that hasn't confirmed yet (pid not set), so stopping the
  // queue mid-launch doesn't orphan the process.
  const p = pendingSpawns.get(String(id));
  if (p && p.exitCode === null) killChild(p);
  pendingSpawns.delete(String(id));
  return !!e;
}

function statusFor(id) {
  const e = active.get(String(id));
  if (!e) return null;
  return {
    id: String(e.id || id),
    name: e.name,
    exe: e.exe,
    pid: e.pid,
    running: e.child && e.child.exitCode === null,
    exitedEarly: !!e.exitedEarly,
    exitCode: e.exitCode,
    hideWindow: !!e.hide,
    elapsedSec: Math.floor((Date.now() - e.startedAt) / 1000),
    durationSec: e.durationSec,
    file: e.file,
  };
}

function allStatus() {
  return [...active.keys()].map(statusFor).filter(Boolean);
}

function listProcesses() {
  return new Promise((resolve) => {
    let cmd, args;
    if (process.platform === 'win32') { cmd = 'tasklist'; args = ['/FO', 'CSV', '/NH']; }
    else { cmd = 'ps'; args = ['-eo', 'comm=']; }
    try {
      const c = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'ignore'] });
      let out = '';
      c.stdout.on('data', (d) => (out += d));
      c.on('error', () => resolve(null));
      c.on('exit', () => resolve(out));
      setTimeout(() => { try { c.kill(); } catch (_) {} }, 4000);
    } catch (_) { resolve(null); }
  });
}

/* -------------------------------- Router -------------------------------- */

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const p = url.pathname;
  try {
    if (req.method === 'GET' && (p === '/' || p === '/index.html')) {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(UI_HTML);
    }
    if (req.method === 'GET' && p === '/api/health') {
      return sendJson(res, 200, { ok: true, platform: process.platform, baseDir: BASE_DIR, count: active.size, version: VERSION });
    }
    if (req.method === 'GET' && p === '/api/games') {
      const games = await getGames(url.searchParams.get('refresh') === '1');
      return sendJson(res, 200, { count: games.length, games });
    }
    if (req.method === 'GET' && p === '/api/status') {
      const list = allStatus();
      if (list.length) {
        const out = await listProcesses();
        if (out) {
          const lower = out.toLowerCase();
          list.forEach((s) => {
            const base = path.basename(s.file).toLowerCase();
            s.confirmed = lower.includes(base);
          });
        }
      }
      return sendJson(res, 200, { active: list, queue: queueState() });
    }
    if (req.method === 'POST' && p === '/api/start') {
      const body = await readBody(req);
      const st = await startSim(body);
      return sendJson(res, 200, { ok: true, status: st });
    }
    if (req.method === 'POST' && p === '/api/stop') {
      const body = await readBody(req);
      if (body.id === 'all') { stopQueue(); return sendJson(res, 200, { ok: true, active: allStatus() }); }
      return sendJson(res, 200, { ok: stopSim(body.id), active: allStatus() });
    }
    if (req.method === 'POST' && p === '/api/queue/run') {
      const body = await readBody(req);
      const ok = await startQueue(Array.isArray(body.items) ? body.items : []);
      if (!ok) { sendJson(res, 400, { error: 'empty queue' }); return; }
      return sendJson(res, 200, { ok: true, queue: queueState() });
    }
    if (req.method === 'POST' && p === '/api/queue/stop') {
      stopQueue();
      return sendJson(res, 200, { ok: true, queue: queueState() });
    }
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'not found' }));
  } catch (e) {
    sendJson(res, 500, { error: e.message });
  }
});

/* -------------------------------- Startup ------------------------------- */

server.listen(PORT, HOST, () => {
  log('Discord Game Simulator running at http://' + HOST + ':' + PORT);
  log('Fake games are written to ' + BASE_DIR);
  openBrowser('http://' + HOST + ':' + PORT);
});

server.on('error', (err) => {
  if (err && err.code === 'EADDRINUSE') {
    log('');
    log('Port ' + PORT + ' is already in use — a Discord Game Simulator is already running.');
    log('Opening the existing one in your browser…');
    openBrowser('http://' + HOST + ':' + PORT);
    // Close this window shortly after so it doesn't just sit there doing nothing.
    setTimeout(() => process.exit(0), 1500);
  } else {
    log('Failed to start the server:', err && err.message ? err.message : err);
    log('Close this window to exit.');
    process.exitCode = 1;
  }
});

// Never die silently: a crash should show a reason, not a hanging window.
process.on('uncaughtException', (e) => {
  log('');
  log('Unexpected error:', e && e.stack ? e.stack : e);
  log('Close this window to exit.');
  process.exitCode = 1;
});
process.on('unhandledRejection', (e) => {
  log('');
  log('Unhandled rejection:', e && e.stack ? e.stack : e);
  log('Close this window to exit.');
  process.exitCode = 1;
});

function openBrowser(url) {
  const cmds = {
    win32:  ['cmd.exe', ['/c', 'start', '', url]],
    darwin: ['open', [url]],
  };
  const [bin, args] = cmds[process.platform] || ['xdg-open', [url]];
  try {
    // windowsHide: don't flash a cmd.exe window just to open the browser.
    const c = spawn(bin, args, { stdio: 'ignore', detached: true, windowsHide: true });
    c.on('error', () => {});   // headless / missing opener: ignore
    c.unref();
  } catch (_) {}
}

/* Export the core for unit testing (no-op when run directly). */
if (require.main !== module) {
  module.exports = { startQueue, stopQueue, queueState, pickDuration, randInt, launchJob };
}
